CREATE FUNCTION clinlims.guard_specimen_intake_decision() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'First specimen decision evidence cannot be updated, deleted or truncated' USING ERRCODE = '55000';
END $$;

CREATE TRIGGER specimen_intake_no_mutation BEFORE UPDATE OR DELETE ON clinlims.specimen_intake_decision
  FOR EACH ROW EXECUTE FUNCTION clinlims.guard_specimen_intake_decision();
CREATE TRIGGER specimen_intake_no_truncate BEFORE TRUNCATE ON clinlims.specimen_intake_decision
  FOR EACH STATEMENT EXECUTE FUNCTION clinlims.guard_specimen_intake_decision();

DO $$ BEGIN
  LOCK TABLE clinlims.reference_tables IN SHARE ROW EXCLUSIVE MODE;
  IF (SELECT count(*) FROM clinlims.reference_tables WHERE trim(lower(name)) = 'specimen_intake_decision') > 1
    OR EXISTS (SELECT 1 FROM clinlims.reference_tables WHERE trim(lower(name)) = 'specimen_intake_decision'
      AND (keep_history IS DISTINCT FROM 'Y' OR is_hl7_encoded IS DISTINCT FROM 'N')) THEN
    RAISE EXCEPTION 'Specimen intake audit registration requires explicit reconciliation';
  END IF;
  INSERT INTO clinlims.reference_tables (id, name, keep_history, is_hl7_encoded, lastupdated)
    SELECT nextval('clinlims.reference_tables_seq'), 'specimen_intake_decision', 'Y', 'N', CURRENT_TIMESTAMP
    WHERE NOT EXISTS (SELECT 1 FROM clinlims.reference_tables WHERE trim(lower(name)) = 'specimen_intake_decision');
END $$;
